<!DOCTYPE html>
<html lang="en"><head><meta charset="utf-8">
<script src="https://cdn.jsdelivr.net/npm/p5@1.11.3/lib/p5.min.js"></script>
<style>
  html, body { margin: 0; height: 100%; overflow: hidden; background: #f4efe4; font-family: Georgia, 'Times New Roman', serif; }
  #title { position: fixed; left: 24px; top: 18px; color: #3c3a33; pointer-events: none; }
