// One big button that speaks. The words compare with the person's own
// usual days (the median of the four weeks before), never with a fixed goal.
let days = [];
const fmt = (n) => Math.round(n).toLocaleString('en-GB');
const median = (a) => { const s = [...a].sort((x, y) => x - y); const m = s.length >> 1; return s.length % 2 ? s[m] : (s[m - 1] + s[m]) / 2; };

window.onBioframe = function (frame) {
  days = frame.data.rows.filter(r => typeof r.steps === 'number');
  document.getElementById('wait').hidden = days.length > 0;
  document.getElementById('app').hidden = !days.length;
};

// Speak in the language of the text, not the computer's default language.
const LANG = 'en-GB';
function englishVoice() {
  const voices = speechSynthesis.getVoices();
  return voices.find(v => v.lang === LANG) || voices.find(v => v.lang.startsWith('en')) || null;
}

function say(text) {
  document.getElementById('said').textContent = text;
  if (!('speechSynthesis' in window)) return;
  speechSynthesis.cancel();
  const u = new SpeechSynthesisUtterance(text);
  u.lang = LANG;
  const voice = englishVoice();
  if (voice) u.voice = voice;
