const dayLong = (d) => new Date(d + 'T00:00').toLocaleDateString('en-GB', { weekday: 'long' });
const dateShort = (d) => new Date(d + 'T00:00').toLocaleDateString('en-GB', { day: 'numeric', month: 'long' });

document.querySelectorAll('[data-view]').forEach(b => b.onclick = () => {
