  document.getElementById('week').innerHTML = worn.slice(-7).map(r =>
    `<div><div class="dot ${level(r.steps)}" title="${r.steps.toLocaleString('en-GB')} steps">${r.weekday[0]}</div><div class="lvl">${words[level(r.steps)]}</div></div>`).join('');
}

function family(rows, worn, level) {
  const hrs = worn.map(r => r.resting_heart_rate).filter(num);
  const hrNormal = ss.median(hrs), spread = ss.medianAbsoluteDeviation(hrs) || 1;
  const high = (r) => num(r.resting_heart_rate) && r.resting_heart_rate >= hrNormal + 3 * spread;
  const offset = (new Date(rows[0].date + 'T00:00').getDay() + 6) % 7;
  let html = '<b></b>' + ORDER.map(d => `<b style="text-align:center">${d}</b>`).join('');
  const cells = Array(offset).fill('<span></span>').concat(rows.map(r =>
    `<span class="${level(r.steps)}${high(r) ? ' h' : ''}" title="${r.date}"></span>`));
  for (let w = 0; w * 7 < cells.length; w++) html += `<b>week ${w + 1}</b>` + cells.slice(w * 7, w * 7 + 7).join('');
  document.getElementById('cal').innerHTML = html;

  // The longest run of days with a raised resting heart rate, in words.
  let run = [], best = [];
  for (const r of worn) { if (high(r)) { run.push(r); if (run.length > best.length) best = [...run]; } else run = []; }
  if (best.length >= 3) {
    const steps = ss.mean(best.map(r => r.steps)), hr = ss.mean(best.map(r => r.resting_heart_rate));
    const n = document.getElementById('heartNote'); n.hidden = false;
    n.textContent = `From ${dateShort(best[0].date)} to ${dateShort(best[best.length - 1].date)}, resting heart rate was higher than usual ` +
      `(${Math.round(hr)} instead of ${Math.round(hrNormal)}) and they moved less (${Math.round(steps).toLocaleString('en-GB')} steps a day). ` +
      `A quieter week with a reason, not a failure.`;
  }
  const by = ORDER.map(d => { const v = worn.filter(r => r.weekday === d); return { d, steps: v.length ? ss.mean(v.map(r => r.steps)) : 0, out: v.length ? ss.mean(v.map(r => r.outdoor_minutes || 0)) : 0 }; })
    .sort((a, b) => b.steps - a.steps).slice(0, 2);
  document.getElementById('helps').textContent =
    `${by.map(b => LONG[b.d] + 's').join(' and ')} ` +
    `are their most active days: about ${Math.round(ss.mean(by.map(b => b.steps))).toLocaleString('en-GB')} steps and ${Math.round(ss.mean(by.map(b => b.out)))} minutes outside. ` +
    `What happens on those days may be worth asking about.`;
}
